import{_ as d,o as t,c as o,aS as r}from"./chunks/framework.DsJaIkSj.js";const h=JSON.parse('{"title":"ADR：QyTable renderer 职责基线","description":"","frontmatter":{},"headers":[],"relativePath":"adr/2026-08-29-qytable-renderer-responsibility-baseline.md","filePath":"adr/2026-08-29-qytable-renderer-responsibility-baseline.md","lastUpdated":null}'),c={name:"adr/2026-08-29-qytable-renderer-responsibility-baseline.md"};function a(l,e,n,i,s,y){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-qytable-renderer-职责基线" tabindex="-1">ADR：QyTable renderer 职责基线 <a class="header-anchor" href="#adr-qytable-renderer-职责基线" aria-label="Permalink to &quot;ADR：QyTable renderer 职责基线&quot;">​</a></h1><p>日期：2026-08-29 状态：Accepted</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p><code>QyTable</code> 当前在满足 virtual 准入条件时使用 <code>VxeVirtualTableRenderer</code>，否则使用 <code>ElementTableRenderer</code>。两者都是内部 adapter；业务侧只依赖 Qy props、events、slots 和 <code>QyTableExpose</code>。这份 ADR 固化后续收敛职责时的判断基线，而非宣称任一 renderer 已经可以无差别替换。</p><p>审计以当前源码、<code>@qynpm/table-schema</code> 和本地安装的 <code>vxe-table@4.21.0</code> 的公开类型、 配置、事件及实例方法为依据。<code>$el</code>、厂商 store/reactData、列对象字段和依赖 CSS class 查询到的 DOM 都不是可新增的长期依赖；本 ADR 中提到它们时，仅是在记录当前实现需要 后续以公开 API 或 Qy 语义证明后才能保留的事实。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><ol><li>VXE 负责虚拟 DOM、实际滚动与尺寸计算、fixed 列，以及它已公开提供的基础表格 交互。未来能力默认首先以 <strong>VXE-native adapter</strong> 评估，而不是在 Qy 层重造表格引擎。</li><li>Qy 负责公开 interface、受控状态与事件顺序、完整树先序的 canonical <code>rowIndex</code>、 业务 schema，以及 VXE 无法表达或与 Qy 契约不一致的语义。</li><li><code>ElementTableRenderer</code> 和 <code>table-schema</code> 都只是内部 adapter。前者不定义公共行为， 后者负责列 schema、展示/编辑/action 映射，不能取得 renderer 的状态所有权。</li><li>新增或收敛能力只能使用 VXE 的公开 props/config、公开事件和公开实例方法；不把 DOM、store、reactive internal state 或 VXE column object 暴露给业务，也不以它们作为 新架构方案。</li><li>下表的 <code>Evidence Required</code> 表示当前源码或 VXE 类型不足以证明可替换；在原生对照 测试、Qy 契约测试和需要时的真实 DOM 证据齐备前，保持现有 Qy-owned 语义。</li></ol><h2 id="现状与职责矩阵" tabindex="-1">现状与职责矩阵 <a class="header-anchor" href="#现状与职责矩阵" aria-label="Permalink to &quot;现状与职责矩阵&quot;">​</a></h2><p>标记含义：<strong>VXE Native</strong> 为可由 VXE 4.21 公共能力承载；<strong>Qy Adapter</strong> 为内部映射； <strong>Qy Owned</strong> 为不能交给厂商的稳定语义；<strong>Evidence Required</strong> 为替换或扩大支持前必须 补齐的证据。一个能力可同时有多个标记。</p><table tabindex="0"><thead><tr><th>能力</th><th>当前实现位置与状态所有者</th><th>VXE 4.21 公共能力</th><th>Qy 契约差异与建议归属</th><th>重复/测试现状</th><th>标记</th></tr></thead><tbody><tr><td>纵向、横向虚拟化</td><td><code>VxeVirtualTableRenderer</code> 以 <code>scroll-y</code>、<code>virtual-x-config</code>、固定 <code>cell-config.height</code> 配置；VXE 拥有虚拟窗口。</td><td><code>scroll-y</code>、<code>virtual-x-config</code>、<code>recalculate</code>、<code>refreshScroll</code>、<code>scrollTo</code>。</td><td>Qy 决定 virtual 准入、<code>virtualMinRows/Columns</code>、固定行高和 fallback；窗口实现继续交给 VXE。</td><td><code>QyTable.spec.ts</code> 覆盖横向窗口/fixed 和 layout；真实浏览器窗口数仍须独立验收。</td><td>VXE Native、Qy Owned、Evidence Required</td></tr><tr><td>滚动、尺寸、layout、锚点</td><td>虚拟 renderer 用 <code>ResizeObserver</code>、<code>recalculate</code>/<code>refreshScroll</code> 和 key+offset 锚点；当前也读取 <code>$el</code>/DOM 和 render width。</td><td><code>getScroll</code>/<code>getScrollData</code>、<code>scrollTo</code>、<code>scrollToRow</code>、<code>scrollToColumn</code>、<code>recalculate</code>、<code>refreshScroll</code>。</td><td>VXE 负责实际尺寸和滚动；Qy 保留稳定 row/column key 锚点和受控重投影后的恢复。不得把 <code>$el</code>、class 查询或列内部宽度作为未来方案。</td><td>有 <code>doLayout</code>、列设置和横向锚点单测；公开方法与真实 resize 的原生对照待补。</td><td>VXE Native、Qy Owned、Evidence Required</td></tr><tr><td>selection、reserve、selectable、Shift、current</td><td>两 renderer 各自同步 selected/current；虚拟 renderer 维护 canonical selectable、range endpoint 与 reserve 缓存。</td><td><code>checkbox-config.reserve/checkMethod/isShiftKey</code>、checkbox/current 事件，以及 <code>setCheckboxRow</code>、<code>setAllCheckboxRow</code>、<code>clearCheckboxRow</code>、<code>setCurrentRow</code>。</td><td>Qy 拥有 <code>selectedRowKeys</code>、完整树先序 rowIndex、受控父级拒绝后的顺序和树投影范围；平铺 Shift 可优先使用 VXE range payload。</td><td>Element 与 QyTable 测试覆盖受控同步；虚拟选择有专门测试。先补 VXE 原生 range/current 对照，再删除重复同步。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>树投影、树/详情展开</td><td>虚拟 renderer 自建 canonical tree、筛选/排序后的可见平铺和 expand key；Element 交给 ElTable tree。</td><td><code>tree-config</code>、<code>toggleTreeExpand</code>/<code>setTreeExpand</code>；详情有 <code>expand-config</code>、<code>toggleRowExpand</code>/<code>setRowExpand</code>。</td><td>Qy 的一个 key 同时控制子树与详情、过滤临时展开、清筛恢复和 canonical index 均超出直接替换边界；维持 Qy-owned 投影。</td><td>QyTable 树/expand 覆盖较多，但没有“VXE 原生完整等价”证据。</td><td>Qy Owned、Qy Adapter、Evidence Required</td></tr><tr><td>排序、筛选</td><td>虚拟 renderer 在 Qy projected tree 中本地排序/筛选；VXE header 仅保持状态（<code>sort-config.remote</code>）。</td><td><code>sort-change</code>、<code>filter-change</code>、<code>sort</code>/<code>setSort</code>/<code>clearSort</code>、<code>clearFilter</code>。</td><td>Qy 拥有 custom 不重排、树递归筛选、同列 OR/跨列 AND、稳定兄弟排序和公共 key/order。</td><td><code>QyTable.spec.ts</code> 有 local/custom/expose 覆盖；不能以 header 成功替代投影语义。</td><td>Qy Owned、Qy Adapter、Evidence Required</td></tr><tr><td>fixed、列设置</td><td><code>table-schema</code> 合并 visible/fixed/width/order；renderer 映射到 El/VXE。</td><td>VXE column <code>fixed</code>、<code>setColumnFixed</code>、<code>setColumnWidth</code>、<code>hideColumn</code>/<code>showColumn</code>、<code>refreshColumn</code>。</td><td>Qy 拥有受控 <code>columnSettings</code> 序列化与列 key；VXE 负责 fixed 布局和实际列定位。</td><td>table-schema core 与 QyTable layout/设置测试存在；更多公开列定位委托仍需对照。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>编辑生命周期</td><td><code>table-schema</code> 产生 schema；<code>VxeVirtualEditCell</code> 维护虚拟窗口中的唯一编辑会话、草稿和提交；Element 使用现有编辑 renderer。</td><td>VXE 可承载 cell/edit 配置，但当前 Qy 没有把编辑协议交给 VXE。</td><td>Qy 拥有 <code>controlProps/options</code>、写回、<code>cell-value-change</code>、异步 options 和 data/columns/renderer 更换时静默取消。</td><td>edit cell、schema 和 QyTable 已有测试；原生编辑能否满足全部生命周期未证明。</td><td>Qy Owned、Qy Adapter、Evidence Required</td></tr><tr><td>图片与 action 浮层生命周期</td><td>虚拟 renderer 自持 image preview、error 和 popover key；<code>table-schema</code> 提供 image/action 数据映射。</td><td>无需把 Qy image/action 协议映射为 VXE 私有浮层。</td><td>Qy 拥有按 rowKey/columnKey 的生命周期、权限、关闭时机和 runtime；renderer 只挂载可见单元格。</td><td>image/schema、virtual edit/image 与 action 相关测试存在；teleport、滚出窗口和 query reset 仍须真实 DOM 证据。</td><td>Qy Owned、Qy Adapter、Evidence Required</td></tr><tr><td>分组表头</td><td>Qy column <code>children</code> 定义递归分组；两 renderer 投影可见叶子，VXE mixed fixed 分组按 left/main/right 重建且分组时关闭横向列虚拟。</td><td>VXE 支持 column group。</td><td>Qy 拥有 group schema、slot/context、同父级 settings 顺序和 fixed 分区语义；VXE 只承载渲染。</td><td>QyTable 覆盖递归、隐藏/空组、mixed fixed、profile 与能力叶子；真实 DOM 组合留给独立验收。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>body 合并、Footer 汇总</td><td><code>spanMethod</code> 只由 Element renderer 承载并强制 fallback；<code>summary</code> 由 Qy 解析 canonical rows，两个 renderer 使用各自 Footer。</td><td>VXE 提供 <code>span-method</code> 与 footer 能力，但当前不用于 public span。</td><td>Qy 拥有 span 投影、受限列/fixed 分区 fallback 与 summary scalar/slot 协议；不透传厂商 cell/column。</td><td>span resolver、summary resolver、QyTable 与专用演示已有覆盖；浏览器组合仍须独立验收。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>区域选择、复制（未来）</td><td>现有只有单元格 <code>copy</code> schema/runtime；当前未装载 VXE 区域模块，区域复制尚未开放。</td><td>区域 selection/copy 只有在模块、安装版类型和公共事件确认后才可评估。</td><td>Qy 定义剪贴板 payload、权限和跨 renderer 事件，不泄漏 VXE 区域对象。</td><td>仅现有 copy/schema 测试；区域选择没有原生对照。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>懒加载树</td><td>Qy-owned coordinator 负责 loader、single-flight、缓存、Abort、错误/重试与 renderer 切换；renderer 只触发展开。</td><td>tree lazy/load 及 tree expand 实例方法可作为 adapter 候选。</td><td>Qy 拥有加载 authority、稳定字符串 key、展开事件顺序和失效请求处理；loader context 不暴露 VXE 类型。</td><td>coordinator、集成测试和 10,000 节点轻量演示已覆盖；真实浏览器缓存/中止路径仍须独立验收。</td><td>Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>列拖拽</td><td><code>columnDraggable</code> 仅在 VXE virtual renderer 通过公开 column drag 配置/事件启用；Element 不支持。</td><td>VXE 4.21 公开 column drag 配置、事件与图标 slot。</td><td>Qy 仍只提交完整 <code>columnSettings</code>；支持范围限当前已挂载横向列窗口，跨窗口自动滚动落点为 Unsupported/Deferred。</td><td>policy 与 QyTable 覆盖 accept/reject、隔离和外部 authority；当前窗口真实拖拽留给独立验收。</td><td>VXE Native、Qy Adapter、Qy Owned、Evidence Required</td></tr><tr><td>动态行高（未来）</td><td>virtual 模式明确只支持 <code>virtualRowHeight</code> 固定高度；详情另以内部滚动限制高度。</td><td>VXE 提供行高/重算相关公开方法，但与虚拟窗口的完整组合不能由方法名推断。</td><td>继续禁止在当前 virtual contract 中声明动态高度；若启用，Qy 要定义锚点漂移、详情、合并和树的语义。</td><td>固定高与详情限制有测试；动态高无对照。</td><td>Qy Owned、Evidence Required</td></tr></tbody></table><h2 id="vxe-组合限制" tabindex="-1">VXE 组合限制 <a class="header-anchor" href="#vxe-组合限制" aria-label="Permalink to &quot;VXE 组合限制&quot;">​</a></h2><p>以下不是产品禁令，而是默认的实现门槛：在对应原生组合测试和 Qy 契约测试通过前， 不开放或不替换现有行为。</p><ul><li>tree checkbox range：平铺数据可评估 <code>isShiftKey</code> 与 range 事件；树投影不把原生 range 当作 Qy 的完整树先序语义。</li><li><code>spanMethod</code> 当前强制 Element fallback；通用动态行高与 virtual 仍不组合。详情 expand 使用固定基础行高和内部限高滚动，行窗口、锚点和详情高度继续以真实 DOM 证明。</li><li>tree、懒加载、排序筛选：原生树状态不能替代 Qy 的递归筛选、稳定排序和受控 key 事件顺序。</li><li>列拖拽与 fixed/column settings：提交后的 Qy <code>columnSettings</code> 才是唯一持久状态；只保证 当前已挂载横向列窗口内拖拽，跨窗口自动滚动落点保持 Unsupported/Deferred。</li></ul><h2 id="后续收敛方向" tabindex="-1">后续收敛方向 <a class="header-anchor" href="#后续收敛方向" aria-label="Permalink to &quot;后续收敛方向&quot;">​</a></h2><h3 id="低风险-继续收敛公开滚动与-layout" tabindex="-1">低风险：继续收敛公开滚动与 layout <a class="header-anchor" href="#低风险-继续收敛公开滚动与-layout" aria-label="Permalink to &quot;低风险：继续收敛公开滚动与 layout&quot;">​</a></h3><ul><li>范围：维持 <code>QyTableExpose</code> 的 Qy-owned 滚动方法和基于 VXE <code>scrollTo</code>、<code>recalculate</code>、 <code>refreshScroll</code> 的 resize/layout；继续用公开 render width 替换仅存于详情高度测量的 DOM 证据。</li><li>验收：Qy key/offset 恢复测试、真实 resize/fixed DOM 路径和详情高度的独立证据。</li><li>不做：不暴露 VXE instance、column object、<code>$el</code> 或 CSS class。</li></ul><h3 id="中风险-收敛平铺-selection-current-expand" tabindex="-1">中风险：收敛平铺 selection/current/expand <a class="header-anchor" href="#中风险-收敛平铺-selection-current-expand" aria-label="Permalink to &quot;中风险：收敛平铺 selection/current/expand&quot;">​</a></h3><ul><li>范围：先建立 VXE native 与 Qy 并排测试，覆盖 reserve、selectable、Shift、current、 tree/详情 expand 的 controlled/uncontrolled 事件顺序；仅对已等价的平铺路径移除重复同步。</li><li>验收：每一项同时证明原生事件 payload、Qy emits、受控父级拒绝恢复和 canonical rowIndex。</li><li>不做：不把树 range 或详情/树共 key 的投影委托给 VXE。</li></ul><h3 id="高风险-仅在原生完整满足-qy-契约时替换" tabindex="-1">高风险：仅在原生完整满足 Qy 契约时替换 <a class="header-anchor" href="#高风险-仅在原生完整满足-qy-契约时替换" aria-label="Permalink to &quot;高风险：仅在原生完整满足 Qy 契约时替换&quot;">​</a></h3><ul><li>范围：树投影、排序筛选和编辑/浮层生命周期分别做原生能力 spike；只有原生实现能 完整满足 Qy 的投影、事件顺序、编辑取消、权限和窗口卸载语义时才替换局部实现。</li><li>验收：完整 Qy contract matrix、真实虚拟 DOM/teleport 证据、组合限制矩阵；任一缺口 保持 Qy-owned。</li><li>不做：不以绿色 build、内部 store 或单个 VXE demo 作为替换依据。</li></ul><h2 id="审计证据" tabindex="-1">审计证据 <a class="header-anchor" href="#审计证据" aria-label="Permalink to &quot;审计证据&quot;">​</a></h2><ul><li>Qy facade 与公共类型：<code>packages/table/src/table/QyTable.vue</code>、<code>types.ts</code>。</li><li>现有两个内部 adapter：<code>ElementTableRenderer.vue</code>、<code>VxeVirtualTableRenderer.vue</code>；后者 当前使用 <code>scroll-y</code>、<code>virtual-x-config</code>、<code>checkbox-config</code>、<code>expand-config</code>、公开事件 和公开实例方法，同时包含本 ADR 明确不应扩散的 <code>$el</code>/DOM 读取。</li><li>schema 与 renderer-neutral column 映射：<code>packages/table/src/table/adapters/table-schema.ts</code> 及 <code>packages/table-schema/src</code>。</li><li>现有行为证据：<code>packages/table/__tests__/QyTable.spec.ts</code>、 <code>ElementTableRenderer.spec.ts</code>、<code>VxeVirtualEditCell.spec.ts</code>、table-schema 测试。</li><li>VXE 公开面：本地 <code>node_modules/.pnpm/vxe-table@4.21.0/node_modules/vxe-table</code> 的 <code>types/index.d.ts</code>、<code>types/all.d.ts</code> 与 table 实现导出的配置/事件/实例方法；版本同时由 <code>packages/table/package.json</code> 的 devDependency 固定。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./2026-08-06-current-element-implementation-and-future-renderer-seam">当前 Element Plus implementation 与未来 renderer seam</a></li><li><a href="./../01-architecture">架构</a></li><li><a href="./../packages/table">QyTable 包 README</a>（源码证据：<code>packages/table/README.md</code>）</li></ul>',24)])])}const p=d(c,[["render",a]]);export{h as __pageData,p as default};
